  },
  Skill_117315_tempBattleDesc_2 = {
    Text = "Mengakibatkan <Damage:[Damage:Arg1]> poin kerusakan, mendapatkan 3 lapisan <ZuiyinKeywords:jejak dosa>. Setelah dimainkan, kartu ini akan diacak dan ditempatkan di bagian atas tumpukan gambar. Pada kali ke-3 dimainkan, <DepleteIconKeywords:lelah> dan membuat kartu perintah berikutnya dari pemilik menikmati efek \"penebusan penderitaan\" dan berlaku 2 kali([Arg2]/3)."
  },
  Skill_117315_tempBattleDesc_3 = {
