  Skill_119763_AwakerSkillBackgroundStory = {
    Text = "Dia adalah sosok yang angkuh. Dia menyembunyikan kekosongan dalam hatinya yang tidak dapat diperbaiki dengan sikap angkuhnya. \n Dia melupakan siapa dirinya yang sebenarnya, dia melupakan siapa yang seharusnya dia jadi. \n Ribuan pengikut Pelaut tunduk di bawah kakinya, sementara dia melupakan hal terpenting di tengah pujian yang terus mengalir — \n dia telah menyerah pada takdir yang pucat ini."
  },
  Skill_119763_BattleDesc = {
    Text = "Mendapatkan 2 poin arithmetica, menarik 2 kartu. Pada awal giliran berikutnya akan menerima [Arg3] poin <SacrificeKeyWord: pengorbanan>. <RippleKeywords: gelombang>: Menghapus [Arg4] poin <SacrificeKeyWord: pengorbanan>."
  },
  Skill_119763_Desc = {
    Text = "Dapatkan 2 poin Aritmetika, ambil 2 kartu. Pada awal giliran berikutnya, terima [Arg1]% dari Kesehatan maksimum sebagai <SacrificeKeyWord:Pengorbanan>. <RippleKeywords:Riak>: Hapus <SacrificeKeyWord:Pengorbanan> sebesar [Float:Arg2]% dari Kesehatan maksimum."
  },
