  Skill_119765_AwakerSkillBackgroundStory = {
    Text = [[
Dia adalah sosok yang suka bersenang-senang. Dia melawan kenyataan yang hancur dengan kesenangan. 
 Mari kita menari, katanya, menari untuk mempersembahkan kepada dewa. 
 Terima kasih kepada dewa yang memberikan kita sebab-akibat yang terbalik, masa lalu yang kacau, dan masa depan yang tidak terduga. 
 Di bawah sorotan lampu, dia adalah satu-satunya fokus dari segalanya.]]
  },
  Skill_119765_BattleDesc = {
    Text = "Mendapatkan <Posse:[Arg7]> poin keyflare. Berdasarkan sikap tentakel, dapatkan efek berbeda: \"Arus tinggi\": <TentacleInjurieIconKeywords:Kerusakan tentakel> +[TentaclePower:Arg1], menghasilkan 1 tentakel. \"Lautan tenang\": mendapatkan <Block:[Block:Arg2]> poin perisai, perisai tetap 50% hingga giliran berikutnya. \"Ombak bergelora\": memberikan [Arg3] kali <Damage:[Damage:Arg4]> poin kerusakan pada musuh dengan kehidupan tertinggi, menerima [Arg5]% bonus <TentacleInjurieIconKeywords:Kerusakan tentakel>."
  },
  Skill_119765_Desc = {
    Text = "Mendapatkan keyflare sebesar [Arg6]% dari keyflare regen. Berdasarkan sikap tentakel, dapatkan efek berbeda: \"Arus tinggi\": <TentacleInjurieIconKeywords:Kerusakan tentakel> +[TentaclePower:Arg8], menghasilkan 1 tentakel. \"Lautan tenang\": mendapatkan <Block:[Block:Arg9]> poin perisai, perisai tetap 50% hingga giliran berikutnya. \"Ombak bergelora\": memberikan [Arg3] kali <Damage:[Damage:Arg4]> poin kerusakan pada musuh dengan kehidupan tertinggi, menerima [Arg5]% bonus <TentacleInjurieIconKeywords:Kerusakan tentakel>."
