  Skill_122485_Desc_0 = {
    Text = "Mocha mendapatkan <Energy:[Energy:Arg1]> poin Kegilaan. <ExaltIconKeywords:Kebangkitan Gnosis>: Jumlah hit \"Perjumpaan Dramatis\" +2. Setiap kali memicu \"Perjumpaan Dramatis\", damage akhir sementara \"Serangan\" Mocha +25%. Segera menghasilkan 1 \"Ledakan Dunia\" sementara."
  },
  Skill_122485_Desc_15 = {
    Text = "Moxia mendapatkan <Energy:[Energy:Arg1]> poin Fury. <ExaltIconKeywords:Kebangkitan Gnosis>: Jumlah hit \"Perjumpaan Dramatis\" +2. Batas pemicu per giliran meningkat menjadi 5. Setiap kali \"Perjumpaan Dramatis\" terpicu, damage akhir sementara \"Serangan\" Moxia +25%. Langsung menghasilkan 2 kartu sementara \"Ledakan Duniawi\" dengan konsumsi daya komputasi 0."
  },
