  Skill_122485_Name = {
    Text = "Jejak Kabut"
  },
  Skill_122486_AwakerSkillBackgroundStory = {
    Text = "\"Apakah itu harus diteriakkan di Dunia Lain juga?\"\n\"Baiklah, dengarkan baik-baik—\"\n\"Ayo! Semua orang, tua dan muda, menyukainya! Angin Puting Beliung Bercahaya——!!\""
  },
