  Skill_126488_BattleDesc_0 = {
    Text = "Kehilangan [Float:Arg3]% Max HP( [Arg4] ), dapatkan 1 tumpukan <SilkKeywords:Pemintal>. Dalam pertempuran ini, HP yang hilang dari \"<DerivativeCardKeywords_138:Benang Pemandu>\" dan <CutKeywords:Penghakiman Takdir> yang diberikan Arachne meningkat sebesar [Arg2]%. Void: Arachne secara acak mendapatkan 15~30 poin Aliemus."
  },
  Skill_126488_Desc_0 = {
    Text = "Kehilangan [Arg1]% Max HP, dapatkan 1 tumpukan <SilkKeywords:Pemintal>. Dalam pertempuran ini, HP yang hilang dari \"<DerivativeCardKeywords_138:Benang Pemandu>\" dan <CutKeywords:Penghakiman Takdir> yang diberikan Arachne meningkat sebesar [Arg2]%. Void: Arachne secara acak mendapatkan 15~30 poin Aliemus."
