  Skill_126490_AwakerSkillBackgroundStory = {
    Text = [[
Saat tirai terangkat, boneka-boneka mendongakkan kepala dan melihat wajah lembut di balik roda pemintal.
Benang menegang, di tengah nyanyian dan tarian boneka-boneka, ia tersenyum bak seorang ibu.
Di panggung takdir, ia adalah satu-satunya penonton mereka.]]
  },
  Skill_126490_BattleDesc_0 = {
    Text = "Arachne mendapatkan <Energy:[Energy:Arg1]> poin Aliemus. <ExaltIconKeywords:Rouse>:\"Pembantaian\" diubah menjadi pilih 1 kartu perintah Ruang Ultra dan keluarkan, berikan \"efek tambahan 1 kali saat dimainkan berikutnya\", membuat kartu perintah yang dimainkan berikutnya memicu <SingularityKeywords3:Perjalanan Dimensi>."
  },
  Skill_126490_BattleDesc_15 = {
    Text = "Arachne mendapatkan <Energy:[Energy:Arg1]> poin Aliemus. <ExaltIconKeywords:Rouse>: \"Pembantaian\" berubah menjadi memilih 1 Kartu perintah dari Ruang Ultra untuk diambil, memberikan \"Berlaku tambahan 1 kali setelah di-play berikutnya\", membuat Kartu perintah berikutnya yang di-play memicu <SingularityKeywords3:Penjelajahan Dimensi>. Setelah melepaskan \"Pembantaian\", segera menimbulkan <FixedDamage:Kerusakan Murni> kepada semua musuh setara dengan 50% \"Penghakiman Takdir\", DMG Amplification dan Perisai dari Exalt berikutnya meningkat 50%."
  },
  Skill_126490_Desc_0 = {
    Text = "Arachne mendapatkan [Arg2]% Aliemus dasar. <ExaltIconKeywords:Rouse>:\"Pembantaian\" diubah menjadi pilih 1 Kartu Ruang Ultra dan gunakan agar efeknya berlaku 2 kali saat dimainkan berikutnya, membuat kartu perintah yang dimainkan berikutnya memicu <SingularityKeywords3:Perjalanan Dimensi>."
  },
  Skill_126490_Desc_15 = {
    Text = "Arachne mendapatkan [Arg2]% Aliemus Dasar. <ExaltIconKeywords:Rouse>: \"Pembantaian\" berubah menjadi memilih 1 Kartu perintah dari Ruang Ultra untuk diambil, memberikan \"Berlaku tambahan 1 kali setelah di-play berikutnya\", membuat Kartu perintah berikutnya yang di-play memicu <SingularityKeywords3:Penjelajahan Dimensi>. Setelah melepaskan \"Pembantaian\", segera menimbulkan <FixedDamage:Kerusakan Murni> kepada semua musuh setara dengan 50% \"Penghakiman Takdir\", DMG Amplification dan Perisai dari Exalt berikutnya meningkat 50%."
  },
