  Skill_131856_BattleDesc_0 = {
    Text = "Saya mendapatkan <Energy:[Energy:Arg1]> poin Aliemus. <ExaltIconKeywords:Rouse>: Setelah menggunakan \"Crimson Furnace\", lampirkan <ErosionColorInkKeywords:Kekacauan Kognisi> pada Kartu perintah milik Awakener lain di mana pun yang tidak memiliki \"<DestructionKeywords:Destroy>\". Setiap 3 kali pertama per ronde saat play Kartu perintah yang memiliki <ErosionColorInkKeywords:Kekacauan Kognisi>, Saya dan Awakener pemilik Kartu perintah tersebut mendapatkan <Energy:[Energy:Arg2]> poin Aliemus."
  },
  Skill_131856_BattleDesc_15 = {
    Text = "Saya mendapatkan <Energy:[Energy:Arg1]> poin Aliemus. <ExaltIconKeywords:Rouse>: Setelah menggunakan \"Crimson Furnace\", Saya mendapatkan <Energy:[Energy:Arg4]> poin Aliemus dan 1 tumpukan <KaiHuajishu:Benih Bulu>, menambahkan <ErosionColorInkKeywords:Kekacauan Kognisi> pada Kartu perintah milik Tubuh Terjaga lain di mana pun yang tidak memiliki \"<DestructionKeywords:Destroy>\". Setiap ronde, 3 kali pertama play Kartu perintah yang memiliki <ErosionColorInkKeywords:Kekacauan Kognisi> membuat Saya dan Tubuh Terjaga pemilik Kartu perintah tersebut mendapatkan <Energy:[Energy:Arg2]> poin Aliemus."
  },
  Skill_131856_Desc_0 = {
    Text = "Saya mendapatkan [Arg3]% Kegilaan Dasar. <ExaltIconKeywords:Rouse>:Setelah menggunakan \"Crimson Furnace\", tambahkan <DestructionKeywords:Kekacauan Kognisi> pada kartu perintah Awakener lain yang tidak memiliki \"<ErosionColorInkKeywords:Destroy>\". 3 kali pertama setiap giliran memainkan kartu perintah dengan <ErosionColorInkKeywords:Kekacauan Kognisi> memberikan Saya dan Awakener pemilik kartu perintah tersebut <Energy:[Energy:Arg2]> poin aliemus."
  },
  Skill_131856_Desc_15 = {
    Text = "Saya mendapatkan [Arg3]% Kegilaan Dasar. <ExaltIconKeywords:Rouse>: Setelah menggunakan \"Crimson Furnace\", Saya mendapatkan <Energy:[Energy:Arg4]> poin Aliemus dan 1 lapis <KaiHuajishu:Benih Bulu>, menambahkan <ErosionColorInkKeywords:Kekacauan Kognisi> pada Kartu perintah milik Tubuh Terjaga lain di mana pun yang tidak memiliki \"<DestructionKeywords:Destroy>\". Setiap ronde, 3 kali pertama memainkan Kartu perintah yang memiliki <ErosionColorInkKeywords:Kekacauan Kognisi> membuat Saya dan Tubuh Terjaga pemilik Kartu perintah tersebut mendapatkan <Energy:[Energy:Arg2]> poin Aliemus."
