  Skill_142700_AwakerSkillBackgroundStory = {
    Text = "\"Apa yang kamu inginkan?\"\nKekuatan, ketertiban, mendapatkan kembali yang hilang, membalas dendam dengan Darah…\nIa tenggelam dalam kebisuan yang panjang dan suram, namun sebenarnya ia sudah lama memiliki jawabannya, sebuah jawaban yang tak terpecahkan.\nIa ingin Matahari terbit di timur dan terbenam di barat, ia ingin Segalanya seperti biasa."
  },
  Skill_142700_BattleDesc_0 = {
    Text = "Pontos mendapatkan <Energy:[Energy:Arg1]> poin Aliemus. <ExaltIconKeywords:Rouse>: Setiap ada 3 kartu \"Budak-Gaunt\" di dek, \"Perburuan Tanpa Akhir\" mendapatkan tambahan 1 tumpukan <BattueKeywords:Kelompok Pemburu>. Setiap memainkan 1 kartu Pontos, efek Temporary STR▼ dari \"Perburuan Tanpa Akhir\" berikutnya meningkat sebesar [Arg3]%, maksimal terpicu 3 kali per ronde."
  },
  Skill_142700_BattleDesc_15 = {
    Text = "Pontos mendapatkan <Energy:[Energy:Arg1]> poin Aliemus. <ExaltIconKeywords:Rouse>: Setiap 2 kartu \"Budak-Gaunt\" di dek, \"Perburuan Tanpa Akhir\" mendapatkan tambahan 1 tumpukan <BattueKeywords:Kelompok Pemburu>. Setiap 1 Kartu Pontos yang di-play, efek Temporary STR▼ \"Perburuan Tanpa Akhir\" berikutnya meningkat [Arg3]%, maksimal terpicu 3 kali per giliran. \"Pukulan\" pertama dan \"Pertahanan\" pertama setiap giliran mendapatkan tambahan <Energy:[Energy:Arg4]> poin Aliemus"
  },
  Skill_142700_Desc_0 = {
    Text = "Pontos mendapatkan [Arg2]% Aliemus Dasar. <ExaltIconKeywords:Rouse>: Setiap ada 3 kartu \"Budak-Gaunt\" di dek, \"Perburuan Tanpa Akhir\" mendapatkan 1 tumpukan <BattueKeywords:Kelompok Pemburu>. Setiap memainkan 1 kartu Pontos, efek Temporary STR▼ dari \"Perburuan Tanpa Akhir\" berikutnya meningkat sebesar [Arg3]%, maksimal terpicu 3 kali per ronde."
  },
  Skill_142700_Desc_15 = {
    Text = "Pontos mendapatkan [Arg2]% Kegilaan Dasar. <ExaltIconKeywords:Rouse>: Setiap 2 kartu \"Budak-Gaunt\" di dek, \"Perburuan Tanpa Akhir\" mendapatkan 1 tumpukan <BattueKeywords:Kelompok Pemburu>. Setiap 1 Kartu Pontos yang di-play, efek Temporary STR▼ \"Perburuan Tanpa Akhir\" berikutnya meningkat [Arg3]%, maksimal terpicu 3 kali per giliran. \"Pukulan\" pertama dan \"Pertahanan\" pertama setiap giliran mendapatkan tambahan <Energy:[Energy:Arg4]> poin Aliemus"
