  Skill_144438_Desc_1 = {
    Text = "<PVPWeaponKeywords:Roda takdir>: Saat sekutu mati, diri sendiri mendapatkan <Energy:[Energy:Arg1]> Aliemus. Saat sekutu bangkit kembali, mereka mendapatkan <Energy:[Energy:Arg2]> Aliemus. Efek perolehan Aliemus hanya berlaku saat Aliemus target belum penuh, maksimal berlaku [Arg8] kali, setelah habis Roda takdir ini akan Destroy."
  },
  Skill_144438_Name_1 = {
