  },
  Skill_144486_AwakerSkillBackgroundStory = {
    Text = "Peri dan penyihir itu bertemu di sepetak tanah kosong yang terpencil di sudut sebuah kota kecil.\nSaat itu ia sedang dengan senyum manis merayu anak-anak asing berpakaian mewah, sementara sang penyihir diam-diam mengincar gelang emas yang bergerincing di pergelangan tangan sang ibu.\nPandangan keduanya beradu di udara, seketika saling memahami niat masing-masing.\nDalam persaingan sunyi ini, akhirnya sang penyihir unggul, menang tipis berkat pengalamannya yang mumpuni.\nNamun sebuah usaha baru yang indah — penuh tipu muslihat dan kelicikan — pun dimulai sejak saat itu."
  },
  Skill_144486_BattleDesc_0 = {
    Text = "[<DevouredIconKeywords:Devour>: Dapatkan 1 stack <WormGrowth1:Kepuasan>. Setiap kali memberikan kerusakan, berikan [Corrosion:Arg10] poin <Corrosion:Corrosion> pada target.] Hilangkan status <BurningKeywords2:Terbakar> dari semua kartu di Hand. Dapatkan Perisai sebesar <Block:[Block:Arg2]> poin. Berikan <Damage:[Damage:Arg1]> poin kerusakan kepada semua musuh sebanyak [Arg8] kali. Setiap 1 stack <WormGrowth1:Kepuasan> meningkatkan Kerusakan Dasar Exalt dan Perisai sebesar [Arg6]%. Konsumsi semua <SacrificialMark1:Persembahan>, setiap stack menambah jumlah serangan +1, dan dapatkan <WormGrowth1:Kepuasan>. Stack <WormGrowth1:Kepuasan> saat ini: [Arg9], stack yang terkumpul dalam pertempuran ini: [Arg11]"
  },
  Skill_144486_BattleDesc_3 = {
    Text = "[<DevouredIconKeywords:Devour>: Dapatkan 1 stack <WormGrowth2:Kepuasan>, setiap kali memberikan kerusakan, berikan [Corrosion:Arg10] poin <Corrosion:Corrosion> pada target.] Hilangkan status <BurningKeywords2:Terbakar> dari semua kartu di Hand. Dapatkan Perisai sebesar <Block:[Block:Arg2]> poin. Berikan <Damage:[Damage:Arg1]> poin kerusakan kepada semua musuh sebanyak [Arg8] kali. Setiap 1 stack <WormGrowth2:Kepuasan> meningkatkan Kerusakan Dasar Exalt dan Perisai sebesar [Arg6]%. Konsumsi semua <SacrificialMark1:Persembahan>, setiap stack menambah jumlah serangan +1, dan dapatkan <WormGrowth2:Kepuasan>. Stack <WormGrowth2:Kepuasan> saat ini: [Arg9], stack yang terkumpul dalam pertempuran ini: [Arg11]"
  },
  Skill_144486_Desc_0 = {
    Text = "[<DevouredIconKeywords:Devour>: Dapatkan 1 stack <WormGrowth1:Kepuasan>. Setiap kali memberikan kerusakan, berikan [Corrosion:Arg10] poin <Corrosion:Corrosion> pada target.] Hilangkan status <BurningKeywords2:Terbakar> dari semua kartu di Hand. Dapatkan Perisai sebesar <Block:[Block:Arg2]> poin. Berikan <Damage:[Damage:Arg1]> poin kerusakan kepada semua musuh sebanyak [Arg8] kali. Setiap 1 stack <WormGrowth1:Kepuasan> meningkatkan Kerusakan Dasar Exalt dan Perisai sebesar [Arg6]%. Konsumsi semua <SacrificialMark1:Persembahan>, setiap stack menambah jumlah serangan +1, dan dapatkan <WormGrowth1:Kepuasan>."
  },
  Skill_144486_Desc_3 = {
    Text = "[<DevouredIconKeywords:Devour>: Dapatkan 1 stack <WormGrowth2:Kepuasan>, setiap kali memberikan kerusakan, berikan [Corrosion:Arg10] poin <Corrosion:Corrosion> pada target.] Hilangkan status <BurningKeywords2:Terbakar> dari semua kartu di Hand. Dapatkan Perisai sebesar <Block:[Block:Arg2]> poin. Berikan <Damage:[Damage:Arg1]> poin kerusakan kepada semua musuh sebanyak [Arg8] kali. Setiap 1 stack <WormGrowth2:Kepuasan> meningkatkan Kerusakan Dasar Exalt dan Perisai sebesar [Arg6]%. Konsumsi semua <SacrificialMark1:Persembahan>, setiap stack menambah jumlah serangan +1, dan dapatkan <WormGrowth2:Kepuasan>."
  },
