  Skill_144491_BattleDesc_15 = {
    Text = "Caraboo mendapatkan <Energy:[Energy:Arg1]> poin Aliemus. <ExaltIconKeywords:Rouse>: Setelah menggunakan \"Crimson Furnace\", kurangi Arithmetica Cost \"Berkah Keajaiban\" berikutnya sebesar -3, setiap pilihan <FaxianKeywords:Temuan> berisi 2 kartu <DerivativeCardKeywords_152:\"Berkat\"> tambahan, pilih 1 kelompok untuk dimasukkan ke Menggambar. Setelah play \"Berkat\", Embryo Fusion +10, semakin rendah HP saat ini maka efeknya semakin tinggi, maksimal meningkat 100%."
  },
  Skill_144491_Desc_0 = {
    Text = "Caraboo mendapatkan [Arg2]% Aliemus Dasar. <ExaltIconKeywords:Rouse>: Setelah menggunakan \"Crimson Furnace\", kurangi Arithmetica Cost \"Berkah Keajaiban\" berikutnya sebesar -3, setiap pilihan <FaxianKeywords:Temuan> berisi 1 kartu <DerivativeCardKeywords_152:\"Berkat\"> tambahan, pilih 1 kelompok untuk dimasukkan ke Menggambar."
  },
  Skill_144491_Desc_15 = {
    Text = "Caraboo mendapatkan [Arg2]% Aliemus Dasar. <ExaltIconKeywords:Rouse>: Setelah menggunakan \"Crimson Furnace\", kurangi Arithmetica Cost \"Berkah Keajaiban\" berikutnya sebesar -3, setiap pilihan <FaxianKeywords:Temuan> berisi 2 kartu <DerivativeCardKeywords_152:\"Berkat\"> tambahan, pilih 1 kelompok untuk dimasukkan ke Menggambar. Setelah play <Blessing:Berkah>, Embryo Fusion +10, semakin rendah HP saat ini maka efeknya semakin tinggi, maksimal meningkat 100%."
