  Skill_145677_AwakerSkillBackgroundStory = {
    Text = "Dulu, sang pemuda pernah mencoba melepaskan lumpur hitam jahat itu dari dirinya, namun apa pun yang ia lakukan — merobeknya dengan tangan, memotongnya dengan benda tajam, memukulnya dengan benda tumpul... mimpi buruk yang tak kasat mata itu selalu tak mau pergi, bahkan semakin merajalela.\nPada akhirnya, ia akhirnya mengakui bahwa dirinya dan Dia telah sepenuhnya Menjadi satu, tak terpisahkan.\nDia telah menjadi bayangannya."
  },
  Skill_145677_BattleDesc_0 = {
