  Skill_146016_AwakerSkillBackgroundStory = {
    Text = "Dewa merobek jiwa dan raganya, mengira itulah penghakiman tertinggi atas Chaos.\nNamun jiwa yang kosong tak pernah berhenti mencari, dan kekuatan yang terpisah pun tak pernah benar-benar lenyap.\nKetika zirah tulang kembali menyelimuti tubuhnya, ketika denyut Leviathan kembali Resonansi dengan kehendaknya — semua Pembatasan hancur berkeping-keping di saat itu.\nJiwa dan raga menyatu kembali di kedalaman lautan bintang. Hewan Buas Penghancur tak lagi tak sempurna.\nLautan bintang ini, akan kembali menyambut dirinya yang utuh."
  },
  Skill_146016_BattleDesc_0 = {
    Text = "\"Lotan: Cetarchon\" mendapatkan <Energy:[Energy:Arg1]> poin Aliemus. <ExaltIconKeywords:Rouse>: Jumlah hit Kerusakan Kartu perintah \"Lotan: Cetarchon\" +1. Pada awal giliran, jika <DerivativeCardKeywords_153:\"Bilah Besar: Whalefall\"> ada di tangan, setiap 1 poin Aliemus yang dicuri oleh <DerivativeCardKeywords_154:\"Duel Mematikan\"> pertama kali pada giliran ini, Final DMG \"Pembelah Dunia\" berikutnya +1%, maksimal ditumpuk hingga 90%."
  },
  Skill_146016_BattleDesc_15 = {
    Text = "\"Lotan: Cetarchon\" mendapatkan <Energy:[Energy:Arg1]> poin Aliemus. <ExaltIconKeywords:Rouse>: Jumlah hit Kerusakan Kartu perintah \"Lotan: Cetarchon\" +1, Aliemus yang dicuri oleh <DerivativeCardKeywords_154:\"Duel Mematikan\"> ditingkatkan 50%. Pada awal giliran, jika <DerivativeCardKeywords_153:\"Bilah Besar: Whalefall\"> ada di tangan, setiap 1 poin Aliemus yang dicuri oleh <DerivativeCardKeywords_154:\"Duel Mematikan\"> pertama kali pada giliran ini, Final DMG \"Pembelah Dunia\" berikutnya +1.5%, maksimal ditumpuk hingga 135%."
  },
  Skill_146016_Desc_0 = {
    Text = "\"Lotan: Cetarchon\" mendapatkan [Arg2]% Aliemus Dasar. <ExaltIconKeywords:Rouse>: Jumlah hit Kerusakan Kartu perintah \"Lotan: Cetarchon\" +1. Pada awal giliran, jika <DerivativeCardKeywords_153:\"Bilah Besar: Whalefall\"> ada di tangan, setiap 1 poin Aliemus yang dicuri oleh <DerivativeCardKeywords_154:\"Duel Mematikan\"> pertama kali pada giliran ini, Final DMG \"Pembelah Dunia\" berikutnya +1%, maksimal ditumpuk hingga 90%."
  },
  Skill_146016_Desc_15 = {
    Text = "\"Lotan: Cetarchon\" mendapatkan [Arg2]% Aliemus Dasar. <ExaltIconKeywords:Rouse>: Jumlah hit Kerusakan Kartu perintah \"Lotan: Cetarchon\" +1, Aliemus yang dicuri oleh <DerivativeCardKeywords_154:\"Duel Mematikan\"> ditingkatkan 50%. Pada awal giliran, jika <DerivativeCardKeywords_153:\"Bilah Besar: Whalefall\"> ada di tangan, setiap 1 poin Aliemus yang dicuri oleh <DerivativeCardKeywords_154:\"Duel Mematikan\"> pertama kali pada giliran ini, Final DMG \"Pembelah Dunia\" berikutnya +1.5%, maksimal ditumpuk hingga 135%."
  },
