  Skill_4018_Desc_0 = {
    Text = "Nautila mendapatkan <Energy:[Energy:Arg1]> poin Aliemus. <ExaltIconKeywords: Membangkitkan> : Perisai yang diterapkan Nautila dan <RetaliateIconKeywords: Counter> meningkat [Arg2]%."
  },
  Skill_4018_Desc_15 = {
    Text = "Notera mendapatkan <Energy:[Energy:Arg1]> poin Fury. <ExaltIconKeywords:Kebangkitan Gnosis>: Perisai dan <RetaliateIconKeywords:Serangan Balik> yang diberikan Notera meningkat [Arg2]%, <RetaliateIconKeywords:Serangan Balik> tetap yang diberikan semua Awakened meningkat [Arg3]%."
