  Skill_4018_Name = {
    Text = "Ahli pemeliharaan"
  },
  Skill_4019_AwakerSkillBackgroundStory = {
    Text = "Seperti teori bahwa segala sesuatu berasal dari satu dan kembali ke satu, dia pernah terjebak dalam jebakan paradoks."
  },
  Skill_4019_Desc_0 = {
    Text = "Mendapatkan <Posse:[Arg1]> poin Energi-s. Tempatkan 3 salinan asli dari Kartu Perintah Tidak Turunan yang berbeda yang terakhir dimainkan pada putaran sebelumnya ke dalam tangan, mengurangi konsumsi Aritmetika mereka sebesar 1 dan mendapatkan <DepleteIconKeywords:Lelah> dan <NothingnessIconKeywords:Ilusi>. Jika kartu perintah yang dapat ditempatkan di tangan tidak mencukupi, tarik kartu dengan jumlah yang sama sebagai pengganti."
  },
  Skill_4019_Desc_3 = {
    Text = "Mendapatkan <Posse:[Arg1]> poin Energi-s kunci perak. Tempatkan 3 salinan asli dari Kartu Perintah Tidak Turunan yang berbeda yang terakhir dimainkan pada putaran sebelumnya ke dalam tangan, mengurangi konsumsi Aritmetika mereka sebesar 1 dan mendapatkan <DepleteIconKeywords:Lelah> dan <NothingnessIconKeywords:Ilusi>. Jika kartu perintah yang dapat ditempatkan di tangan tidak mencukupi, tarik kartu dengan jumlah yang sama sebagai pengganti. Pilih 1 Posse yang telah dibuka untuk menggantikan Posse saat ini, gunakan Posse atau setelah pertempuran berakhir untuk memulihkan."
  },
  Skill_4019_EffectNameList = {
    Text = "Keyflare Regen"
  },
  Skill_4019_Name = {
    Text = "Penyatuan Paradoks"
  },
  Skill_4019_OverLimitUtlSkillDesc_0 = {
    Text = "Dapatkan <Posse:[Arg1]> poin Keyflare. Masukkan Salinan Primitif dari 3 Kartu Perintah Tidak Turunan yang berbeda yang terakhir di-play pada giliran sebelumnya ke dalam Hand, buat Arithmetica Cost-nya menjadi 0 dan dapatkan <DepleteIconKeywords:Konsumsi> dan <NothingnessIconKeywords:Void>. Jika Kartu Perintah yang dapat dimasukkan ke Hand tidak mencukupi, Draw Kartu sejumlah yang kurang sebagai gantinya. Dapatkan 3 tumpukan <TimeBeacon2:Negentropy> yang mengabaikan batas maksimum."
  },
  Skill_4019_OverLimitUtlSkillDesc_3 = {
    Text = "Mendapatkan <Posse:[Arg1]> poin Energi-s kunci perak. Tempatkan 3 salinan asli dari Kartu Perintah Tidak Turunan yang berbeda yang terakhir dimainkan pada putaran sebelumnya ke dalam tangan, mengubah konsumsi Aritmetika mereka menjadi 0 dan mendapatkan <DepleteIconKeywords:Lelah> dan <NothingnessIconKeywords:Ilusi>. Jika kartu perintah yang dapat ditempatkan di tangan tidak mencukupi, tarik kartu dengan jumlah yang sama sebagai pengganti. Pilih 1 Geng yang telah dibuka untuk menggantikan Geng saat ini, gunakan Geng atau setelah pertempuran selesai untuk memulihkan. Dapatkan 3 lapisan <TimeBeacon2:Negentropy> tanpa batas."
