  Skill_4315_AwakerSkillBackgroundStory = {
    Text = [[
Lindungi aku. Lindungi aku. Lindungi aku.
Monster pengecut, sama seperti dia, seolah memiliki kehidupan, namun tanpa kesadaran.
Lendir hitam berkumpul menjadi pelayannya, tanpa henti siang dan malam dipandu oleh perintah.]]
  },
  Skill_4315_Desc_0 = {
    Text = "Lily memperoleh <Energy:[Energy:Arg1]> poin Aliemus.<ExaltIconKeywords:Gnosis>: Di awal putaran, mendapatkan 10% Kesehatan maksimum<PainWord:Bertahan>. Saat Lily menerapkan Perisai, dia menerapkan [Poison:Arg2] lapisan<IntoxicationIconKeywords:Racun> pada musuh dengan kesehatan tertinggi."
  },
  Skill_4315_Desc_15 = {
    Text = "Lily mendapatkan <Energy:[Energy:Arg1]> poin Furor. <ExaltIconKeywords:Kebangkitan Gnosis>: Di awal giliran mendapatkan <PainWord:Ketahanan> sebesar 10% HP maksimal. Saat Lily memberikan perisai, memberikan [Poison:Arg2] lapis <IntoxicationIconKeywords:Racun> kepada musuh dengan HP tertinggi. Ledakan Furor membuat setiap kali menerima 1 serangan pada giliran ini, efek konsumsi <PainWord:Ketahanan> dari \"Serangan Balasan\" berikutnya meningkat 40%, maksimal 5 tumpukan."
