  Skill_4579_AwakerSkillBackgroundStory = {
    Text = [[
Dukun berkata: "Jumlah orang-orang kafir sangat banyak
 sepertinya kita di Levant lemah. 
 Saudara Uvhash, bunyikan terompetmu,
 bertarunglah seperti orang gila."
 Prajurit menjawab: "Di sini tidak ada orang kafir.
 Kalian semua akan dibunuh olehku, mayat tidak mengenal suku atau kepercayaan.
 Saat itu tubuh akan memenuhi lembah, menutupi puncak gunung,
 maka itulah yang akan aku persembahkan sebagai Alunan Darah dan Pasir."]]
  },
  Skill_4579_BattleDesc_0 = {
    Text = "[<DevouredIconKeywords:Melahap>: Kerusakan dari \"Nyanyian Darah dan Pasir\" yang dilepaskan selanjutnya dalam pertempuran ini meningkat sebesar [Arg4] poin, dan kelipatan kekuatan meningkat sebesar [Arg3] kali.] Menyebabkan <Damage:[Damage:Arg1]> poin kerusakan kepada semua musuh. <PowerIconKeywords:Kekuatan> Memberikan efek [Arg2] kali lebih besar pada \"Nyanyian Darah dan Pasir\". Uvhash memperoleh <Energy:[Energy:Arg5]> poin Aliemus."
  },
  Skill_4579_Desc_0 = {
    Text = "[<DevouredIconKeywords:Melahap>: Kerusakan dari \"Alunan Darah dan Pasir\" yang dilepaskan setelah ini meningkat sebesar [Arg4] poin, dan kelipatan Kekuatan meningkat [Arg3] kali.] Menyebabkan <Damage:[Damage:Arg1]> poin kerusakan kepada semua musuh. <PowerIconKeywords:Kekuatan> memberikan efek [Arg2] kali pada \"Alunan Darah dan Pasir\". Mendapatkan Aliemus setara dengan dua kali muatan Aliemus Uvhash."
  },
