  Skill_4581_AwakerSkillBackgroundStory = {
    Text = [[
Di bawah gereja terdapat ruang tersembunyi.

Uskup berlutut di depan tablet, melantunkan mantra rahasia yang tersisa sejak awal penciptaan.

Rune yang dilupakan oleh waktu memancarkan cahaya sebagai respons, sesuai dengan kehendak uskup, bayangan besar muncul, memberikan "Berkat" dari Pencipta kepada mereka yang diselimuti oleh cahayanya.]]
  },
  Skill_4581_Desc_0 = {
    Text = "[<DevouredIconKeywords:Melahap>: Mendapatkan [Power:Arg1] poin sementara <PowerIconKeywords:Kekuatan>, Crit. Rate sementara +[Arg4]%.] Mendapatkan <Block:[Block:Arg2]> poin Perisai. <VulnerabilityIconKeywords:Rentan> semua musuh selama 1 putaran. Hingga awal putaran berikutnya, saat diserang, [Arg3]% kerusakan akan dialihkan menjadi jumlah pemulihan Dapur Merah."
  },
  Skill_4581_Desc_3 = {
    Text = "[<DevouredIconKeywords:Melahap>: Mendapatkan [Power:Arg1] poin <PowerIconKeywords:Kekuatan> sementara, Crit. Rate sementara +[Arg4]%.] Mendapatkan <Block:[Block:Arg2]> poin Perisai. <VulnerabilityIconKeywords:Rentan> semua musuh selama 1 giliran. Hingga awal giliran berikutnya, saat menerima serangan, akan mengubah [Arg3]% dari kerusakan menjadi jumlah pemulihan Dapur Merah. Salvador mendapatkan [Arg5]% Crit. DMG sementara."
  },
