  },
  Skill_4581_OverLimitUtlSkillDesc_0 = {
    Text = "[<DevouredIconKeywords:Devour>: Mendapatkan [Power:Arg1] poin <PowerIconKeywords:Strength> sementara, Tingkat Kritis Sementara +[Arg4]%.] Mendapatkan <Block:[Block:Arg2]> poin Perisai. <VulnerabilityIconKeywords:Vulnerable> semua musuh selama 1 ronde. Hingga ronde berikutnya dimulai, saat menerima serangan, [Arg6]% dari Kerusakan akan dikonversi menjadi pemulihan Crimson Furnace. Membuat \"Serangan Dasar\" dan \"Akhir penderitaan\" milik Salvador mendapatkan bonus 100% Strength tambahan. Dalam eksplorasi ini, batas atas Crimson Furnace meningkat sebesar 2% dari Max HP, maksimal meningkat 10%."
  },
  Skill_4581_OverLimitUtlSkillDesc_3 = {
    Text = "[<DevouredIconKeywords:Melahap>:Dapatkan [Power:Arg1] poin sementara <PowerIconKeywords:Kekuatan>, Tingkat kritis sementara +[Arg4]%.]Dapatkan <Block:[Block:Arg2]> poin perisai. <VulnerabilityIconKeywords:Rentan> semua musuh selama 1 giliran. Hingga giliran berikutnya dimulai, saat menerima serangan, akan mengubah [Arg6]% dari kerusakan menjadi pemulihan Tungku Merah. Salvador memperoleh [Arg5]% penguatan kerusakan kritis sementara. Basic Strike dan [Akhir Penderitaan] Salvador mendapat tambahan penguatan sebesar 100% dari kekuatan. Selama eksplorasi ini, batas maksimum pemulihan Tungku Merah meningkat sebesar 2% dari kesehatan maksimum, hingga maksimum 10%."
  },
