  Skill_4655_AwakerSkillBackgroundStory = {
    Text = "Lautan adalah tempat yang dalam dan tenang, ia membawa harapan akan kehidupan serta ketakutan akan kematian. \n Namun, ada orang yang ingin mengisi lautan dengan tawa dan permainan — saat Aurita mengajukan undangan seperti itu, perasaan \"ikut bermain dengannya sekali tidak masalah\" selalu muncul di hati, membiarkan kebahagiaan sederhana memenuhi dada."
  },
  Skill_4655_Desc_0 = {
    Text = "Menyebabkan <Damage:[Damage:Arg1]> poin kerusakan. Mengonsumsi hingga 10 kartu \"Pemisahan Kelenjar\" dari tumpukan kartu menggambar dan tumpukan kartu buang, setiap kartu memberikan 1 kali kerusakan tambahan. Tempatkan 2 kartu \"Pemisahan Kelenjar\" ke tangan. Meningkatkan kerusakan yang diberikan oleh \"Aurita\" dalam pertempuran ini sebesar [Arg2] poin."
  },
  Skill_4655_Desc_2 = {
    Text = "Mengakibatkan <Damage:[Damage:Arg1]> poin <PunctureDamagewords:kerusakan tusukan>. Menghabiskan maksimum 10 kartu \"Perpecahan kelenjar\" dari tumpukan gambar dan tumpukan kartu buang, setiap kartu memberikan 1 tambahan kerusakan. Tempatkan 2 kartu \"Perpecahan kelenjar\" ke dalam tangan. Meningkatkan kerusakan yang dilakukan \"Aurita\" selama pertempuran ini sebanyak [Arg2] poin."
  },
  Skill_4655_EffectNameList = {
    Text = "Kerusakan, peningkatan kerusakan berikutnya"
  },
  Skill_4655_Name = {
    Text = "Samudera yang Ramai"
  },
  Skill_4655_OverLimitUtlSkillDesc_0 = {
    Text = "Menyebabkan <Damage:[Damage:Arg1]> poin Kerusakan. Mengonsumsi hingga 10 kartu \"Pembagian kelenjar\" dari Menggambar dan Discard Pile, setiap kartu menyebabkan 1 kali Kerusakan tambahan. Menempatkan 2 kartu \"Pembagian kelenjar\" ke tangan. Meningkatkan Kerusakan yang diberikan \"Aurita\" dalam pertarungan ini sebesar [Arg2] poin. Mendapatkan [Power:Arg2] poin <PowerIconKeywords:Strength> dan [TentaclePower:Arg2] poin <TentacleInjurieIconKeywords:Kerusakan tentakel>, setiap 5 kali berikutnya memainkan \"Pembagian kelenjar\", akan Draw 1 kartu."
  },
  Skill_4655_OverLimitUtlSkillDesc_2 = {
    Text = "Menyebabkan <Damage:[Damage:Arg1]> poin <PunctureDamagewords:kerusakan tusukan>. Menghabiskan hingga 10 kartu \"Gland Split\" di tumpukan gambar dan kartu buangan, masing-masing menyebabkan 1 kali kerusakan tambahan. Tempatkan 2 kartu \"Gland Split\" di tangan. Tingkatkan kerusakan yang disebabkan selanjutnya oleh \"Aurita\" dalam pertempuran ini sebanyak [Arg2] poin. Dapatkan [Power:Arg2] poin <PowerIconKeywords:kekuatan> dan [TentaclePower:Arg2] poin <TentacleInjurieIconKeywords:kerusakan tentakel>, lalu untuk 5 kali berikutnya memainkan \"Gland Split\", setiap kali ambil 1 kartu."
  },
