  Skill_4660_AwakerSkillBackgroundStory = {
    Text = "Satu dua, satu dua... \n Dia mengangkat nampan, melangkah dengan irama ringan di antara kerumunan orang. \n Para tamu terus-menerus minum dan bernyanyi, sementara dia terus-menerus menyajikan hidangan dan tersenyum. \n Segalanya di sini berwarna emas. Aula emas, anggur emas, dan juga rok emas. \n Karen menyukai emas. Dia memamerkan senyuman khas yang telah dilatih berkali-kali. \n \"Silakan dinikmati, Tuan——!!\""
  },
  Skill_4660_Desc_0 = {
    Text = "Hapus semua status <SlowIconKeywords:Lambat> dari kartu di tangan. Pulihkan <Heal:[Heal:Arg1]> poin hidup. Tambahkan 1 kartu <DerivativeCardKeywords_42:\"Masakan Ajaib\"> ke tangan. Berikan [Poison:Arg2] lapisan <IntoxicationIconKeywords:Racun> kepada semua musuh."
  },
  Skill_4660_Desc_3 = {
