  },
  Skill_4660_OverLimitUtlSkillDesc_3 = {
    Text = "Buang semua kartu di tangan dengan <SlowIconKeywords:Kelambatan> status. Mengembalikan <Heal:[Heal:Arg1]> poin hidup. Masukkan 1 kartu <DerivativeCardKeywords_43:\"Masakan Ajaib\"> ke tangan. Memberikan [Poison:Arg2] tumpukan <IntoxicationIconKeywords:Racun> pada semua musuh. Masukkan 1 kartu <DerivativeCardKeywords_43:\"Masakan Ajaib\"> ke dalam tumpukan gambar dan tumpukan kartu buang masing-masing 1."
  },
