  Skill_4663_AwakerSkillBackgroundStory = {
    Text = [[
Mesin yang dingin menggantikan jantung, cairan minyak dalam pipa hidrolik menggantikan darah segar. Dia seharusnya dingin, rasional, dan bertindak sesuai perintah. 
 Namun, sebuah kehendak asing bergerak diam-diam di dalam tubuhnya. Dia tidak membutuhkan darah, tidak membutuhkan suhu, hanya dengan dirinya sendiri dia bisa membakar niat jahat yang bukan manusia. Dia berkata: Tunduklah, makhluk yang hina dan lemah, lalu hancurkan dalam bola listrikku yang membara.]]
  },
  Skill_4663_BattleDesc_0 = {
    Text = "Mendapatkan [Power:Arg1] poin <PowerIconKeywords:Kekuatan> sementara. Mendapatkan <Posse:[Arg2]> poin Energi-s. Menghilangkan <WeaknessIconKeywords:Kelemahan> pada diri sendiri. Setiap kali 1 kartu masuk ke <DimensionalSpaceIconKeywords:Ruang Ultra>, berubah menjadi <DerivativeCardKeywords_14:\"Persenjataan Mekanik - Kumpul\">."
  },
  Skill_4663_BattleDesc_1 = {
    Text = "Mendapatkan [Power:Arg1] poin sementara <PowerIconKeywords:Kekuatan>. Mendapatkan <Posse:[Arg2]> poin Energi-s. Menghilangkan status <WeaknessIconKeywords:Kelemahan> pada diri sendiri. Menambahkan 1 kartu \"Serangan\" Erica dengan <DepleteIconKeywords:Lelah> ke dalam tangan. Setiap kali ada 1 kartu yang masuk ke <DimensionalSpaceIconKeywords:Ultra>, berubah menjadi <DerivativeCardKeywords_14:\"Senjata Mekanik - Kumpul\">."
  },
  Skill_4663_Desc_0 = {
    Text = "Mendapatkan [Power:Arg1] poin sementara<PowerIconKeywords:Kekuatan>. Mendapatkan energi-s yang setara dengan pengisian kunci perak Airika. Menghilangkan status <WeaknessIconKeywords:Kelemahan> dari diri sendiri. Setiap kali 1 kartu masuk ke <DimensionalSpaceIconKeywords:Ultra>, berubah menjadi <DerivativeCardKeywords_14:\"Senjata Mekanik - Menyusut\">."
  },
  Skill_4663_Desc_1 = {
    Text = "Mendapatkan [Power:Arg1] poin sementara<PowerIconKeywords:Kekuatan>. Mendapatkan energi-s yang setara dengan pengisian kunci perak Airika. Menghilangkan status <WeaknessIconKeywords:Kelemahan> dari diri sendiri. Menempatkan 1 kartu\"Serangan\"dari Airika yang dilengkapi dengan <DepleteIconKeywords:Lelah> ke dalam tangan. Setiap kali 1 kartu masuk ke <DimensionalSpaceIconKeywords:Ultra>, berubah menjadi <DerivativeCardKeywords_14:\"Senjata Mekanik - Menyusut\">."
