  Skill_4664_AwakerSkillBackgroundStory = {
    Text = [[
Wabah tak terlihat datang tanpa suara, membawa penderitaan tanpa akhir dan kegilaan. 

Uskup tidak bisa tidur di malam hari, merasa sangat terpukul karena tidak bisa menghilangkan penderitaan orang-orang. 

"Ya Tuhan yang Maha Penyayang, selamatkanlah mereka, aku bersedia menanggung semua penderitaan dan kesedihan mereka."

Maka, sang Bapa memberikan "Berkat"kepadanya, memerintahkannya untuk mengukir firman ilahi pada tablet batu, melakukan tugas menghapus penderitaan dan kesulitan.]]
  },
  Skill_4664_Desc_0 = {
    Text = "Salvador memperoleh <Energy:[Energy:Arg1]> poin Aliemus.<ExaltIconKeywords:Gnosis>: Menempatkan 1 <B02AFKeyWord:Cinta adalah melindungi> ke dalam tangan. Setelah putaran berakhir, mendapatkan [Power:Arg2] poin<PowerIconKeywords:Kekuatan>."
  },
  Skill_4664_Desc_15 = {
    Text = "Salvador mendapatkan <Energy:[Energy:Arg1]> Kegilaan. <ExaltIconKeywords:Kebangkitan Gnosis>: Menempatkan 1 kartu <B02AFKeyWord:Lindungi dengan Kasih> ke tangan. Setelah giliran berakhir, mendapatkan [Power:Arg2] <PowerIconKeywords:Kekuatan>. Tungku Merah yang dikumpulkan oleh \"Perlindungan Sang Pencipta\" dan \"Darah yang Diberkati\" meningkat 25%, saat \"Penderitaan yang Harus Dihapus\" memilih \"Pembebasan\", efek peningkatan damage akhir per 1% HP maks Tungku Merah yang dikonsumsi meningkat dari 2% menjadi 5%."
  },
