  Skill_4668_AwakerSkillBackgroundStory = {
    Text = [[
Dia tidak bisa menerima kenyataan bahwa dia hampir mati. Seharusnya dia tak terkalahkan, seharusnya dia tidak bisa dihancurkan. Jika tubuh manusia adalah penghalang bagi dirinya untuk mencapai puncak kekuatan, maka dia akan melepaskan tubuhnya; jika mengorbankan kaumnya dapat membuatnya kuat, maka dia akan mengubur masa lalunya. 
 Dia melemparkan pedang raksasa ke dalam Aequor, meminjam kekuatan yang tidak manusiawi, bersumpah untuk menjadi penguasa segalanya. 
 Bahkan keberadaan yang memberinya kekuatan, di masa depan pasti akan tergeletak di bawah kakinya.]]
  },
  Skill_4668_Desc = {
    Text = "Pilih: <O06_AFKeyWord1:Merebut> atau <O06_AFKeyWord2:Berdiam>. Tempatkan 3 kartu <DerivativeCardKeywords_17:\"Kekuatan pedang besar\"> ke dalam tangan."
  },
  Skill_4668_EffectNameList = {
