  Skill_4822_AwakerSkillBackgroundStory = {
    Text = [[
Dalam pengembaraan tanpa akhir, Tinct telah melupakan nama Rumah-nya.
Dalam perjalanan waktu yang panjang, alam semesta telah melupakan nama Planet mati itu.
Ia dan banyak Planet lain yang terlarut dan ditinggalkan disebut secara kolektif sebagai "Planet Sunyi".
Nyanyiannya mungkin adalah sisa-sisa suara terakhir dari Planet di luar batas itu.]]
  },
  Skill_4822_Desc_0 = {
    Text = "Tinct mendapatkan <Energy:[Energy:Arg1]> poin Aliemus, <ExaltIconKeywords: Membangkitkan>: Meningkatkan kerusakan dasar \"Serangan\" Tinct sebesar [Arg2]%, semua kartu Tinct mendapatkan 1 efek acak, efek tersebut akan dihapus saat pertempuran berakhir."
  },
  Skill_4822_Desc_15 = {
    Text = "Tinkter mendapatkan <Energy:[Energy:Arg1]> poin Kegilaan, <ExaltIconKeywords:Kebangkitan Gnosis>: Meningkatkan damage dasar \"Serangan\" Tinkter sebesar [Arg2]%, semua kartu Tinkter mendapatkan 1 efek acak, efek tersebut akan dihapus saat pertempuran berakhir. Saat Tinkter pertama kali memainkan \"Skill\" setiap giliran, menghasilkan 1 \"Serangan\" sementara dengan konsumsi daya komputasi 0, efek acak \"Serangan\" tersebut menjadi 2 kali lipat."
  },
