  Skill_59476_AwakerSkillBackgroundStory = {
    Text = "Sebelum mendengar melodi ini, kamu tak pernah benar-benar \"memiliki telinga\". Setelah mendengar melodi ini, kamu tak akan pernah menemukan suara seperti itu lagi. Jadi, fokuslah sepenuhnya, tahan napas, dan nikmati dengan sepenuh hati lagu langka seumur hidup ini!"
  },
  Skill_59476_Desc_0 = {
    Text = "Hameln mendapatkan <Energy:[Energy:Arg1]> poin Aliemus. <ExaltIconKeywords:Rouse>: Pada awal giliran, tempatkan 1 kartu \"<DerivativeCardKeywords_64:Simfoni Keharmonisan>\" ke tangan. <DerivativeCardKeywords_61:><DerivativeCardKeywords_62:>"
  },
  Skill_59476_Desc_15 = {
    Text = "Hameln mendapatkan <Energy:[Energy:Arg1]> poin Aliemus. <ExaltIconKeywords:Rouse>: Pada awal giliran, tempatkan 1 kartu \"<DerivativeCardKeywords_64:Simfoni Keharmonisan>\" ke tangan. Pada awal giliran, untuk setiap 1 kartu perintah yang memiliki \"Melodi\", Hameln mendapatkan <Energy:[Energy:Arg2]> poin Aliemus. Saat melepaskan \"Nada Primal\", untuk setiap 2 kartu perintah yang memiliki Melodi, jumlah hit damage +1<DerivativeCardKeywords_61:><DerivativeCardKeywords_62:>"
  },
  Skill_59476_EffectNameList = {Text = "Aliemus"},
  Skill_59476_Name = {
    Text = "Lagu ini layak dipuji"
  },
  Skill_59477_AwakerSkillBackgroundStory = {
    Text = "Dari mana musik berasal? Dari upacara pengorbanan yang menyenangkan, dari teriakan para petani, dari jeritan manusia primitif, dari kicauan burung di musim semi, dari angin pinus dan ombak laut, dari getaran bumi dan runtuhnya gunung... Atau dari kekacauan langit dan bumi, dari delirium dalam mimpi para dewa."
  },
  Skill_59477_BattleDesc_0 = {
    Text = "Secara acak menyebabkan [Arg3] kali <Damage:[Damage:Arg1]> poin <PunctureDamagewords:Menembus DMG>, setiap kali menyebabkan kerusakan sementara mengurangi [Exhaustion:Arg2] poin <ExhaustionIconKeywords:Kekuatan> target dan mendapatkan [Power:Arg2] poin <PowerIconKeywords:Kekuatan sementara>. Pilih 1 kartu perintah yang tidak memiliki \"Melodi\", tidak habis, dan tidak turunan dari tanganmu untuk menambahkan \"<HuihuanaKeywords:Loop Melodi>\". Setiap kali jika tidak ada kartu di tangan yang dapat ditambahkan, sebagai gantinya menyebabkan 3 kali kerusakan tambahan."
  },
  Skill_59477_BattleDesc_2 = {
    Text = "Secara acak menyebabkan [Arg3] kali <Damage:[Damage:Arg1]> poin <PunctureDamagewords:Menembus> kerusakan, setiap kali menyebabkan kerusakan sementara mengurangi [Exhaustion:Arg2] poin <ExhaustionIconKeywords:Kekuatan> target dan mendapatkan [Power:Arg2] poin <PowerIconKeywords:Kekuatan sementara>. Pilih 1 kartu perintah di tangan yang tidak memiliki \"Melodi\", tidak habis, dan tidak turunan untuk menambahkan \"<HuihuanbKeywords:Loop>\". Setiap kali jika tidak ada kartu di tangan yang bisa ditambahkan, ganti dengan menyebabkan 3 kali kerusakan tambahan."
  },
  Skill_59477_Desc_0 = {
    Text = "Secara acak menyebabkan 3 kali <Damage:[Damage:Arg1]> poin <PunctureDamagewords:Kerusakan Tembus>, setiap kali menyebabkan kerusakan <TouquKeywords:mencuri> [Arg2] poin <PowerIconKeywords:Kekuatan> dari target. Pilih 1 Kartu perintah di tangan yang tidak memiliki \"Melodi\", tidak habis, dan tidak turunan untuk menambahkan \"<HuihuanaKeywords:Rondino>\". Setiap kali jika tidak ada kartu di tangan yang dapat ditambahkan, sebagai gantinya menyebabkan 3 kali kerusakan tambahan."
  },
  Skill_59477_Desc_2 = {
    Text = "Secara acak menyebabkan 3 kali <Damage:[Damage:Arg1]> poin <PunctureDamagewords:Kerusakan Tembus>, setiap kali menyebabkan kerusakan <TouquKeywords:mencuri> [Arg2] poin <PowerIconKeywords:Kekuatan> dari target. Pilih 1 kartu perintah di tangan yang tidak memiliki \"Melodi\", tidak habis, dan tidak turunan untuk menambahkan \"<HuihuanbKeywords:Rondino>\". Setiap kali jika tidak ada kartu di tangan yang dapat ditambahkan, ganti dengan menyebabkan 3 kali kerusakan tambahan."
  },
  Skill_59477_EffectNameList = {
    Text = "Kerusakan, mencuri Kekuatan"
  },
  Skill_59477_Name = {
    Text = "Nada Primal"
  },
  Skill_59477_OverLimitUtlSkillDesc = {
    Text = "Secara acak menyebabkan <Damage:[Damage:Arg1]> poin <PunctureDamagewords:kerusakan tusukan> [Arg3] kali, setiap kali menyebabkan 1 kali kerusakan sementara menurunkan [Exhaustion:Arg2] poin <ExhaustionIconKeywords:Kekuatan> target, mendapatkan [Power:Arg2] poin <PowerIconKeywords:Kekuatan sementara>, dan memberikan 1 jenis <MysterydebuffKeywords:Efek Negatif Ajaib> secara acak kepada target. Pilih 2 kartu perintah di tangan yang tidak memiliki \"Melodi\", tidak habis, dan tidak turunan untuk menambahkan \"<HuihuanbKeywords:Rondino>\". Setiap kali jika tidak ada kartu di tangan yang dapat ditambahkan, menyebabkan 3 kali kerusakan tambahan."
  },
