  Skill_59478_AwakerSkillBackgroundStory = {
    Text = "Jika jiwa dapat dipecah, apakah yang membentuknya adalah not-not? Tinggi dan rendah, cepat dan lambat, tangisan kelahiran baru dan jeritan kematian dimainkan bersama. Dengarkanlah, nyanyikan dengan lantang, inilah pembukaan yang menggambarkan wujud jiwamu."
  },
  Skill_59478_BattleDesc = {
    Text = "Secara acak menyebabkan [Arg2] kali <Damage:[Damage:Arg1]> poin <PunctureDamagewords:Kerusakan Tembus>, setiap kali menyebabkan kerusakan memiliki 50% kemungkinan untuk memberikan 1 jenis <MysterydebuffKeywords:Efek Negatif Ajaib> pada target secara acak. Jika saat play konsumsi aritmetika adalah 0, menyebabkan 2 kali kerusakan tambahan."
  },
  Skill_59478_Desc = {
