  Skill_61122_BattleDesc = {
    Text = "Dianggap sebagai \"Pukulan\". Menyebabkan <Damage:[Damage:Arg1]> kerusakan, kerusakan ini mendapatkan bonus 5 kali kekuatan dan memicu 30% <BleedingIconKeywords:Berdarah> pada target, mengembalikan [Arg3]% dari hidup yang hilang (<Heal:[Arg2]>). Setelah digunakan, berubah menjadi \"<DerivativeCardKeywords_65:Helot>\"."
  },
  Skill_61122_Desc = {
    Text = "Dipandang sebagai \"Serangan\". Menyebabkan <Damage:[Damage:Arg1]> poin kerusakan, kerusakan ini menikmati bonus kekuatan 5 kali dan memicu 30% dari <BleedingIconKeywords: berdarah>, memulihkan 15% dari hidup yang hilang. Setelah digunakan, menjadi \"<DerivativeCardKeywords_65: Rantai Darah>\"."
