  },
  Skill_61123_AwakerSkillBackgroundStory = {
    Text = [[
Bernyanyilah, wahai dewi! Bernyanyilah tentang takdir putri Delos: 
Penuh dengan darah dan air mata, kemarahan, dan keputusasaan. 
Kebenciannya seperti api yang membakar habis segala sesuatu di sekitarnya, dan pada akhirnya, 
membawa kematian atas dirinya sendiri.]]
  },
  Skill_61123_Desc_0 = {
    Text = "Helot-catena mendapatkan <Energy:[Energy:Arg1]> poin kegilaan. <ExaltIconKeywords:Membangkitkan jiwa>: Menyimpan satu kartu \"<DerivativeCardKeywords_65:Rantai Darah>\" di tangan, kartu perintah Helot-catena mendapatkan \"<RetainIconKeywords:Pelihara>\". Pada awal putaran, kerusakan dasar Helot-catena meningkat [Arg2]% dalam pertempuran ini."
  },
  Skill_61123_Desc_15 = {
    Text = "Blood Chain·Shilo mendapatkan <Energy:[Energy:Arg1]> poin Fury. <ExaltIconKeywords:Kebangkitan Gnosis>: Menempatkan satu kartu \"<DerivativeCardKeywords_65:Rantai Darah>\" ke tangan, kartu perintah Blood Chain·Shilo mendapatkan \"<RetainIconKeywords:Pertahankan>\". Saat giliran dimulai, damage dasar Blood Chain·Shilo meningkat [Arg2]% dalam pertempuran ini. Setelah melepaskan ledakan Fury \"Rantai Pengikat\", memberikan 50 lapis <TempPowerKeywords:Penguatan Sementara> pada setiap kartu perintah \"Blood Chain·Shilo\" yang berbeda di tangan."
  },
  Skill_61123_EffectNameList = {
    Text = "Aliemus, Kerusakan meningkat"
  },
  Skill_61123_Name = {
    Text = "Deklarasi Soul Reaper"
  },
