  Skill_70286_Desc_1 = {
    Text = "<PVPWeaponKeywords:Roda takdir>: Saat berakhirnya ronde, semua \"keterampilan\" dari pemegang kartu dalam tangan menyebabkan kerusakan, kesembuhan, dan perisai meningkat [Arg1]%."
