  Skill_70299_AwakerSkillBackgroundStory = {
    Text = [[
Tujuan yang dicari seumur hidupnya kini terletak di depan mata. 
 Pintu hitam pekat memancarkan daya tarik yang mematikan. 
 Sebelum membuka pintu, dia membayangkan 372 kemungkinan kebenaran. 
 Setelah membuka pintu, hanya tersisa satu kebenaran yang enggan dia akui, yaitu yang ke-373. 
 Tanpa pilihan, dia hanya bisa terjatuh. 
 Betapa sialnya, dia dan seluruh dunia.]]
  },
  Skill_70299_BattleDesc = {
    Text = "Tubuh Terjaga lainnya mendapatkan <Energy:[Energy:Arg1]> poin Aliemus, memberikan [Poison:Arg2] tumpukan <IntoxicationIconKeywords:Racun> kepada semua musuh, DMG Amplification Sementara +[Arg3]%."
  },
  Skill_70299_Desc = {
    Text = "Tubuh Terjaga lainnya mendapatkan <Energy:[Energy:Arg1]> poin Aliemus, memberikan [Poison:Arg2] tumpukan <IntoxicationIconKeywords:Racun> kepada semua musuh, DMG Amplification Sementara +[Arg3]%. \"Bentuk Akhir\": Draw tambahan 3 kartu, mendapatkan 3 poin Arithmetica, memicu 50% <IntoxicationIconKeywords:Racun> pada semua musuh, Kegilaan Dasar \"Doll: Inferno\" meningkat 50 poin, maksimal 3 kali."
  },
  Skill_70299_EffectNameList = {
    Text = "Aliemus, Racun, Kerusakan Kuat"
  },
  Skill_70299_Name = {
    Text = "Titik Akhir, Gerbang Kebenaran dan Jurang"
  },
  Skill_70299_OverLimitUtlSkillDesc = {
    Text = "Tubuh Terjaga lainnya mendapatkan <Energy:[Energy:Arg4]> poin Aliemus, memberikan [Poison:Arg2] tumpukan <IntoxicationIconKeywords:Racun> kepada semua musuh, DMG Amplification Sementara +[Arg3]%, <IntoxicationIconKeywords:Racun>, <RetaliateIconKeywords:Counter>, dan Kerusakan Dasar yang disebabkan oleh semua Tubuh Terjaga meningkat 10%. Jika saat ini adalah Pertarungan Pemimpin, dapatkan tambahan 1 tumpukan \"Akhir\"."
  },
