 Ketika dia menarik tangannya kembali, jiwanya telah meleleh seperti lilin.]]
  },
  Skill_70302_BattleDesc_0 = {
    Text = "\"Meltdown·Dor\"mendapatkan <Energy:[Energy:Arg1]> poin Fury. <ExaltIconKeywords:Kebangkitan Gnosis>: Saat akhir giliran, memulihkan <Heal:[Heal:Arg2]> poin HP dan mendapatkan <Energy:[Energy:Arg4]> poin Fury. \"Bentuk Akhir Zaman\": Tidak lagi memulihkan HP, diganti dengan memicu [Arg3]% <IntoxicationIconKeywords:Racun> semua musuh."
  },
  Skill_70302_BattleDesc_15 = {
    Text = "\"Meltdown·Dor\"mendapatkan <Energy:[Energy:Arg1]> poin Fury. <ExaltIconKeywords:Kebangkitan Gnosis>: Setiap memiliki 1 tumpukan\"Akhir Zaman\", Penguatan Damage +8%. \"Penghancuran Kehampaan\"membuat semua Awakened mendapatkan 30% Fury dasar. Saat akhir giliran, memulihkan <Heal:[Heal:Arg2]> poin HP dan mendapatkan <Energy:[Energy:Arg4]> poin Fury. \"Bentuk Akhir Zaman\": Tidak lagi memulihkan HP, diganti dengan memicu [Arg3]% <IntoxicationIconKeywords:Racun> semua musuh."
  },
  Skill_70302_Desc_0 = {
    Text = "\"Mencairkan·Boneka\"mendapatkan <Energy:[Energy:Arg1]> poin Aliemus. <ExaltIconKeywords:Membangkitkan Gnosis>: Pada akhir putaran, memulihkan <Heal:[Heal:Arg2]> poin Hidup dan mendapatkan Aliemus yang setara dengan pemulihan Aliemus diri sendiri. \"Bentuk Akhir\": Tidak lagi memulihkan Hidup, menggantikan dengan memicu [Arg3]% <IntoxicationIconKeywords:Racun> ke semua musuh."
  },
  Skill_70302_Desc_15 = {
    Text = "\"Meltdown·Dor\"mendapatkan <Energy:[Energy:Arg1]> poin Fury. <ExaltIconKeywords:Kebangkitan Gnosis>: Setiap memiliki 1 tumpukan\"Akhir Zaman\", Penguatan Damage +8%. \"Penghancuran Kehampaan\"membuat semua Awakened mendapatkan 30% Fury dasar. Saat akhir giliran, memulihkan <Heal:[Heal:Arg2]> poin HP dan mendapatkan Fury setara dengan pengisian ulang Fury sendiri. \"Bentuk Akhir Zaman\": Tidak lagi memulihkan HP, diganti dengan memicu [Arg3]% <IntoxicationIconKeywords:Racun> semua musuh."
  },
  Skill_70302_EffectNameList = {
    Text = "Aliemus, Pemulihan, Pemicu Racun"
  },
  Skill_70302_Name = {Text = "Wabah Jiwa"},
  Skill_70302_PropertyNameList = {
