  Skill_83779_AwakerSkillBackgroundStory = {
    Text = [[
Air asin yang tak terbatas menelan dirinya, sekaligus melindunginya.
Dalam rasa tenggelam yang membuat tercekik itu, dia merasakan kedalaman laut yang dalam, menyatu dengan kedalaman laut tersebut.
Akhirnya, suatu hari, laut akan sepenuhnya tenang, setiap kapal yang berlayar di permukaan laut akan diberikan ketenangan.
Dia menunggu hari itu, hari kedatangan Negara Dewa.]]
  },
  Skill_83779_Desc_0 = {
    Text = "Koppersant mendapatkan <Energy:[Energy:Arg1]> poin Aliemus. <ExaltIconKeywords:Membangkitkan Gnosis>: Mendapatkan 1 Tentakel, meletakkan 2 kartu \"<DerivativeCardKeywords_106:Panduan>\" ke dalam tangan. Beralih ke postur \"Laut Tenang\" setelah mendapatkan <Block:[Block:Arg2]> poin Perisai, cooldown 3 putaran."
  },
  Skill_83779_Desc_15 = {
    Text = "Corpusant mendapatkan <Energy:[Energy:Arg1]> poin Fury. <ExaltIconKeywords:Kebangkitan Gnosis>: Mendapatkan 1 tentakel, menempatkan 2 kartu \"<DerivativeCardKeywords_106:Navigasi>\" ke tangan, kartu \"Halilintar Penghukum\" dan \"Sinyal Kekacauan\" pertama setiap giliran menempatkan 1 kartu \"<DerivativeCardKeywords_106:Navigasi>\" tambahan ke tangan, efek \"<DerivativeCardKeywords_106:Navigasi>\" meningkat 50%. Setelah beralih ke stance \"Laut Tenang\" mendapatkan <Block:[Block:Arg2]> poin perisai, cooldown 3 giliran."
  },
