  Skill_89776_AwakerSkillBackgroundStory = {
    Text = [[
"Kakak, kamu bilang terbang dengan sayap terus menerus, seberapa tinggi kita bisa terbang? Apakah kita bisa terbang di atas awan, untuk menyentuh bulan dan bintang?"
"Mungkin... bisa, ya? Tapi kita harus memiliki sepasang sayap yang besar dan kuat."
Galaksi dan rasi bintang yang dalam dan penuh mimpi di buku catatan tercermin dalam mimpi dua anak itu, berubah menjadi benih harapan yang tertanam dalam hati mereka.]]
  },
  Skill_89776_Desc_0 = {
    Text = "Castor mendapatkan <Energy:[Energy:Arg1]> poin aliemus. <ExaltIconKeywords:Rouse>:Kerusakan yang dilakukan oleh Castor pasti akan kritikal,\"<DerivativeCardKeywords_107:Helaian Bulu Onyx>\" akan memberikan [Corrosion:Arg2] lapisan <Corrosion:Corrosion> kepada target setelah digunakan, dan perisai yang dipertahankan akan meningkat 50%."
  },
  Skill_89776_Desc_15 = {
    Text = "Castor mendapatkan <Energy:[Energy:Arg1]> poin aliemus. <ExaltIconKeywords:Rouse>:Kerusakan yang dilakukan oleh Castor pasti akan kritikal,\"<DerivativeCardKeywords_107:Helaian Bulu Onyx>\" setelah dimainkan memberikan [Corrosion:Arg2] lapisan <Corrosion:Corrosion> pada target, perisai yang dipertahankan meningkat 50%. Saat pertama kali memainkan Helaian Bulu Onyx setiap giliran, memberikan Corrosion setara dengan bakat \"Bulu Suci Pembersih Dosa\" pada musuh baris depan, HP yang hilang saat Corrosion dihapus meningkat dari 300% menjadi 500%."
  },
