  Skill_95819_BattleDesc = {
    Text = "Hapus semua 「Kenyang」, buang semua kartu di tangan, masukkan kartu yang dihapus melalui <DerivativeCardKeywords_111:「Melahap Jiwa」> ke dalam tangan, ubah konsumsi aritmetika mereka menjadi 0. Pada akhir giliran, jika ada di tangan: secara acak masukkan satu salinan kartu yang dihapus ke dalam tangan, ubah konsumsi aritmetika menjadi 0, dan dapatkan Lelah, Void."
  },
  Skill_95819_Desc = {
    Text = "Hapus semua 「Kenyang」, buang semua kartu di tangan, masukkan kartu yang dihapus melalui <DerivativeCardKeywords_111:「Melahap Jiwa」> ke dalam tangan, ubah konsumsi aritmetika mereka menjadi 0. Pada akhir giliran, jika ada di tangan: secara acak masukkan satu salinan kartu yang dihapus ke dalam tangan, ubah konsumsi aritmetika menjadi 0, dan dapatkan Lelah, Void."
